import abc
import logging

import six

from ta_ue_plugin_android.uepc.background_cmd_registry import BackgroundCmdRegistry
from ta_ue_plugin_android.uepc.ue_pc_logger import LoggerAdapter4EmptyExtra
from ta_ue_plugin_android.uepc.utils import Utils


@six.add_metaclass(abc.ABCMeta)
class UeControlDt(object):
    def __init__(self):
        """Half-Abstract class for control of UE data transfer"""
        raw_logger = logging.getLogger("ute_ue.uepc")
        self.logger = LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UECONTROL'})
        self.background_cmd_registry = BackgroundCmdRegistry()

    def ping_app_server(self, dt_name, ping_cmd):
        """
        Ping external app server from UE with given cmd and save it to background registry
        :param dt_name: Data transfer name
        :param ping_cmd: command to run ping
        :return: None
        """
        self.logger.debug("Starting ping from {} UE. CMD: {}".format(self.get_debug_id(), ping_cmd))
        ping_output_reader = self.run_cmd_and_get_non_blocking_output(ping_cmd)
        self.background_cmd_registry.register_cmd(dt_name, ping_output_reader)

    def is_ping_to_app_server_finished(self, dt_name):
        """
        Checks if ping to app server is finished
        :param dt_name: Data transfer name
        :return: bool
        """
        ping_output_reader = self.background_cmd_registry.get_background_cmd(dt_name)
        if ping_output_reader.is_finish():
            return True
        return False

    def get_ping_report(self, dt_name):
        """
        Returns ping output lines as a list
        :param dt_name:
        :return: list
        """
        self.logger.debug("Getting ping report from background cmd registry")
        ping_output_reader = self.background_cmd_registry.get_background_cmd(dt_name)
        ping_output_lines = Utils().get_non_blocking_reader_result(ping_output_reader)
        self.logger.debug("Received ping output for {} data transfer:\n{}".format(dt_name, ping_output_lines))
        return ping_output_lines

    def release_icmp_data_transfer(self):
        """Release SSH connections, ensure threads are stopped"""
        for cmd_runner in self.background_cmd_registry.background_cmd_registry.values():
            cmd_runner.close()
        self.background_cmd_registry.clear_registry()

    @abc.abstractmethod
    def get_debug_id(self):
        """Get debug id"""
        pass

    @abc.abstractmethod
    def is_ip_interface_setup_supported(self):
        """Does device supports ip interface selection based on ip version and/or network interface name pattern"""
        pass

    @abc.abstractmethod
    def get_ip(self, timeout):
        """Get ip"""
        pass

    @abc.abstractmethod
    def run_cmd_and_get_non_blocking_output(self, cmd):
        """Run cmd"""
        pass

    @abc.abstractmethod
    def get_iperf_fullpath(self):
        """Get iperf filename"""
        pass

    @abc.abstractmethod
    def is_able_to_linux_like_process_kill(self):
        """Can kill processes like linux"""
        pass

    @abc.abstractmethod
    def kill_process_with_phrase(self, process_phrase):
        """Kill processes with phrase provided"""
        pass

    @abc.abstractmethod
    def release_ue(self):
        """Do generic actions on UE instance that needs to be done before next use"""
        pass
